<script setup lang="ts">
import {computed} from "vue"
import type {CalendarEvent} from "../../../contracts/index.ts"
import type {CalendarDay} from "../../../services/calendarTime.ts"
import {useCalendarLayout} from "../composables/useCalendarLayout.ts"

const props = defineProps<{mode: "week" | "month"; days: CalendarDay[]; selectedDay: string; events: CalendarEvent[]; timezone: string; sourceLabel: (source: string) => string}>()
const emit = defineEmits<{"update:selectedDay": [string]; select: [CalendarEvent]}>()
const {eventsForDay} = useCalendarLayout(() => props.timezone)
const selected = computed(() => props.days.find(day => day.key === props.selectedDay) ?? props.days[0])
const selectedEvents = computed(() => selected.value ? eventsForDay(props.events, selected.value).sort((left, right) => new Date(left.startsAt).getTime() - new Date(right.startsAt).getTime()) : [])
const countFor = (day: CalendarDay) => eventsForDay(props.events, day).length
</script>

<template>
  <section class="calendar-mobile-agenda" :class="`calendar-mobile-agenda--${mode}`" :aria-label="`${mode} calendar agenda`"><div v-if="mode === 'week'" class="calendar-mobile-agenda__day-strip" role="tablist" aria-label="Days this week"><button v-for="day in days" :key="day.key" type="button" :class="{active: selected?.key === day.key}" :aria-selected="selected?.key === day.key" @click="emit('update:selectedDay', day.key)"><small>{{ day.weekday }}</small><strong>{{ day.label.split(' ')[0] }}</strong><i v-if="countFor(day)" /></button></div><div v-else class="calendar-mobile-agenda__month-grid" role="grid" aria-label="Days this month"><button v-for="day in days" :key="day.key" type="button" :class="{active: selected?.key === day.key}" :aria-selected="selected?.key === day.key" @click="emit('update:selectedDay', day.key)"><span>{{ day.label.split(' ')[0] }}</span><i v-if="countFor(day)">{{ countFor(day) }}</i></button></div><header><p>{{ mode === 'week' ? 'Selected day' : 'Selected date' }}</p><h2>{{ selected ? `${selected.weekday}, ${selected.label}` : 'Choose a day' }}</h2></header><div class="calendar-mobile-agenda__items"><button v-for="event in selectedEvents" :key="event.eventKey" type="button" @click="emit('select', event)"><time>{{ event.allDay ? 'All day' : new Intl.DateTimeFormat(undefined, {timeZone: timezone, hour: 'numeric', minute: '2-digit'}).format(new Date(event.startsAt)) }}</time><span><strong>{{ event.title }}</strong><small>{{ sourceLabel(event.source) }}</small></span></button><p v-if="!selectedEvents.length">Nothing is scheduled for this day.</p></div></section>
</template>

<style scoped>
