t;text-align:left;cursor:pointer}.calendar-mobile-agenda__items time,.calendar-mobile-agenda__items small,.calendar-mobile-agenda__items p{color:var(--text-muted);font-size:var(--text-size-meta)}.calendar-mobile-agenda__items span{display:grid;gap:var(--space-1)}.calendar-mobile-agenda__items p{margin:0;padding:var(--space-3);text-align:center}}
</style>
